xpath.script:
//
(function () {
    // Parse x_specs JSON et peuple le tableau
    var pmFr = (document.documentElement.lang || '').toLowerCase().indexOf('fr') === 0;
    var PM_SPEC_LABELS_FR = {"Processor": "Processeur", "Storage": "Stockage", "Display": "Écran", "Battery": "Batterie", "System": "Système", "Connectivity": "Connectivité", "Camera": "Appareil photo", "Weight": "Poids", "Case": "Boîtier", "Battery life": "Autonomie", "Water resistance": "Étanchéité", "Sensors": "Capteurs", "Compatibility": "Compatibilité", "Material": "Matière", "Mounting": "Fixation", "Available colours": "Couleurs disponibles", "Power": "Puissance", "Connector": "Connecteur", "Indicator": "Indicateur", "Size": "Taille", "Technology": "Technologie", "Resolution": "Résolution", "Refresh rate": "Taux de rafraîchissement", "Sound": "Son", "Type": "Type"};
    var jsonEl = document.getElementById('pm-specs-json');
    var raw = jsonEl ? jsonEl.getAttribute('data-specs') : '';
    if (raw) {
        try {
            var specs = JSON.parse(raw);
            var table = document.getElementById('pm-specs-table');
            var keys = Object.keys(specs);
            if (table && keys.length) {
                keys.forEach(function (key) {
                    var tr = document.createElement('tr');
                    var tdLabel = document.createElement('td');
                    var tdValue = document.createElement('td');
                    tdLabel.className = 'pm-specs-label';
                    tdValue.className = 'pm-specs-value';
                    tdLabel.textContent = (pmFr && PM_SPEC_LABELS_FR[key]) || key;
                    tdValue.textContent = specs[key];
                    tr.appendChild(tdLabel);
                    tr.appendChild(tdValue);
                    table.appendChild(tr);
                });
            } else if (!keys.length) {
                var empty = document.getElementById('pm-specs-empty');
                if (table) table.style.display = 'none';
                if (!empty) {
                    var p = document.createElement('p');
                    p.style.cssText = 'color:#94a3b8; font-style:italic;';
                    p.textContent = 'Specifications not available.';
                    jsonEl.parentNode.appendChild(p);
                }
            }
        } catch (e) {}
    }

    // Bouton Partager
    function showToast(msg) {
        var t = document.getElementById('pm-toast-specs');
        if (!t) return;
        t.textContent = msg;
        t.classList.add('show');
        setTimeout(function () { t.classList.remove('show'); }, 2800);
    }
    var btn = document.getElementById('pm-share-btn');
    if (!btn) return;
    btn.addEventListener('click', function () {
        var url = window.location.href;
        var name = document.querySelector('h1[itemprop="name"], .product_name h1, h1.o_shop_product_title');
        var title = (name ? name.textContent.trim() : document.title) + ' — Planet Mobil';
        if (navigator.share) {
            navigator.share({ title: title, url: url }).catch(function(){});
        } else {
            navigator.clipboard.writeText(url).then(function () {
                showToast(pmFr ? '✓ Lien copié !' : '✓ Link copied!');
            }).catch(function () {
                var inp = document.createElement('input');
                document.body.appendChild(inp);
                inp.value = url;
                inp.select();
                document.execCommand('copy');
                document.body.removeChild(inp);
                showToast(pmFr ? '✓ Lien copié !' : '✓ Link copied!');
            });
        }
    });
})();
//
